window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-adb98669fa1e0537"]={"versions": [{"id": "FIG-adb98669fa1e0537", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm (Ablauf- und Zeitdiagramm) der Übertragungsmodi im AUTOSAR Communication Modul (AUTOSAR COM, Classic Platform). Es stellt das zeitliche Zusammenspiel der zyklischen I-PDU-Übertragung bei Übertragungsmodusumschaltung (Transmission Mode Selection, TMS) zwischen zwei periodischen Betriebsmodi dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zeitachse: Horizontale Achse t für den zeitlichen Ablauf.\n</li><li>Sendeimpulse (grüne vertikale Pfeile): Tatsächliche Übertragungsaufrufe bzw. Sendezeitpunkte einer I-PDU an die darunterliegende Schicht (PDU Router / Interface).\n</li><li>Regulärer Erwartungszeitpunkt (blau gestrichelter vertikaler Pfeil): Geplanter Sendezeitpunkt nach dem vorherigen Zyklus.\n</li><li>Modusumschaltung / Ereignisse (orange Blitzsymbole mit vertikaler gestrichelter Linie): Aktualisierung eines Signals bzw. Umschaltung des Signalwerts (v=b, v=a) mit Einfluss auf den Übertragungsmodus (TMS).\n</li><li>Zeitparameter t_c1, t_c2: Periodendauern (Cycle Times) der beiden periodischen Übertragungsmodi.\n</li><li>Zeitparameter dt: Mindestabstand (Minimum Delay Time / Deadline Monitoring) zwischen zwei aufeinanderfolgenden Übertragungen derselben I-PDU.\n</li><li>Zeitparameter t_r, min: Minimale Reaktionszeit bzw. Umschaltverzögerung nach einem Umschalt-Event bis zur ersten Aussendung im neuen Modus.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das System sendet im ersten periodischen Modus mit der Zykluszeit t_c1.\n</li><li>Nach einer Aussendung wird ein Mindestabstand dt überwacht.\n</li><li>Vor dem nächsten regulären t_c1-Sendezeitpunkt tritt ein Signalwechsel v=b auf (Blitzsymbol), der eine Umschaltung des Übertragungsmodus bewirkt.\n</li><li>Nach Verstreichen der Mindestumschaltzeit t_r, min startet die zyklische Übertragung im zweiten Modus mit dem Periodenintervall t_c2 (hier vier aufeinanderfolgende Zyklen).\n</li><li>Vor dem nächsten regulären t_c2-Sendezeitpunkt tritt erneut ein Signalwechsel v=a auf.\n</li><li>Der eigentlich fällige t_c2-Sendeimpuls (blau gestrichelt) unterbleibt; die Aussendung verzögert sich unter Einhaltung des Mindestabstands dt und der Umschaltzeit t_r, min.\n</li><li>Anschließend setzt sich die zyklische Übertragung im Modus mit der Periodendauer t_c1 fort.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Veranschaulicht Use Case 3 der Übertragungsmodusauswahl (TMS) gemäß AUTOSAR COM: Umschaltung zwischen zwei periodischen Übertragungsmodi (Periodic → Periodic).\n</li><li>Spezifiziert das Verhalten bei Signalwertänderungen, die einen TMS-Wechsel triggern: Der neue Übertragungsmodus übernimmt die Steuerung der Zykluszeit, wobei konfigurierte Mindestverzögerungszeiten (dt) und Reaktionszeiten (t_r, min) verhindern, dass I-PDUs unzulässig dicht aufeinanderfolgend an den Bus übergeben werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f890b8d34802e1ff", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm (Ablauf- und Zeitdiagramm) der Übertragungsmodi im AUTOSAR Communication Modul (AUTOSAR COM, Classic Platform). Es stellt das zeitliche Zusammenspiel der zyklischen I-PDU-Übertragung bei Übertragungsmodusumschaltung (Transmission Mode Selection, TMS) zwischen zwei periodischen Betriebsmodi dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zeitachse: Horizontale Achse t für den zeitlichen Ablauf.\n</li><li>Sendeimpulse (grüne vertikale Pfeile): Periodische I-PDU-Sendeereignisse an die unterlagerte Schicht.\n</li><li>Regulärer Erwartungszeitpunkt (blau gestrichelter vertikaler Pfeil): Geplanter Sendezeitpunkt des bisherigen periodischen Rasters.\n</li><li>Modusumschaltung / Signaländerung (rot konturierte Dreiecke mit vertikaler gestrichelter Hilfslinie): Signalwertfestlegung (v=a, v=b, v=a).\n</li><li>Zeitparameter t_c1, t_c2: Zykluszeiten der beiden Übertragungsmodi.\n</li><li>Zeitparameter t_r: Reaktionszeit / Umschaltverzögerung (rot markiert mit geschweifter Klammer) zwischen Signaländerung und erster I-PDU-Aussendung.\n</li><li>Zeitparameter d (bzw. dt): Minimaler Sendeabstand nach vorheriger Aussendung (orange markiert mit geschweifter Klammer).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Initiale Signalbelegung mit v=a: Es erfolgt die zyklische I-PDU-Übertragung mit der Periodendauer t_c1.\n</li><li>Ein Signalwechsel auf v=b leitet die Modusumschaltung ein; nach Ablauf der Umschaltverzögerung t_r erfolgt die erste Aussendung des neuen Modus.\n</li><li>Es folgen vier periodische Aussendungen mit der Zykluszeit t_c2.\n</li><li>Während des letzten t_c2-Intervalls erfolgt ein Signalwechsel zurück auf v=a.\n</li><li>Der reguläre Zykluszeitpunkt von t_c2 (blau gestrichelter Pfeil) wird nicht gesendet; stattdessen erfolgt die Aussendung nach Einhaltung des Mindestabstands d und der Verzögerung t_r.\n</li><li>Anschließend wird die periodische Aussendung im Modus mit der Periodendauer t_c1 über mindestens zwei vollständige Zyklen fortgesetzt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Veranschaulicht Use Case 3 der Übertragungsmodusauswahl (TMS) gemäß AUTOSAR COM: Umschaltung zwischen zwei periodischen Übertragungsmodi (Periodic → Periodic).\n</li><li>Spezifiziert das Verhalten bei Signalwertänderungen, die einen TMS-Wechsel triggern: Der neue Übertragungsmodus übernimmt die Steuerung der Zykluszeit, wobei konfigurierte Mindestverzögerungszeiten (dt) und Reaktionszeiten (t_r, min) verhindern, dass I-PDUs unzulässig dicht aufeinanderfolgend an den Bus übergeben werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2360d72800e23134", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing-Diagramm (Ablauf- und Zeitdiagramm) der Übertragungsmodi im AUTOSAR Communication Modul (AUTOSAR COM, Classic Platform). Es stellt das zeitliche Zusammenspiel der zyklischen I-PDU-Übertragung bei Übertragungsmodusumschaltung (Transmission Mode Selection, TMS) zwischen zwei periodischen Betriebsmodi dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zeitachse: Horizontale Achse t für den zeitlichen Ablauf.\n</li><li>Sendeimpulse (grüne vertikale Pfeile): Periodische I-PDU-Sendeereignisse an die unterlagerte Schicht.\n</li><li>Regulärer Erwartungszeitpunkt (blau gestrichelter vertikaler Pfeil): Geplanter Sendezeitpunkt des bisherigen periodischen Rasters.\n</li><li>Modusumschaltung / Signalaktualisierung (rot konturierte Dreiecke): Externe Ereignisse / Signalwertänderungen (v=a, v=b, v=a).\n</li><li>Zeitparameter t_c1, t_c2: Zykluszeiten der beiden Übertragungsmodi.\n</li><li>Zeitparameter t_r: Umschaltverzögerung (rot markiert mit geschweifter Klammer) zwischen Umschalt-Event und Übertragung.\n</li><li>Zeitparameter dt: Mindestsendeabstand (Minimum Delay Time / Deadline Monitoring), explizit unter jedem Sendeimpuls als orangefarbene Zeitspanne mit geschweifter Klammer eingezeichnet.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Zu Beginn liegt der Zustand v=a vor; die I-PDU wird im Zyklus t_c1 übertragen, wobei nach jeder Aussendung das Mindestabstandsintervall dt aktiv ist.\n</li><li>Ein Umschalt-Event v=b tritt auf; nach der Reaktionszeit t_r wird die erste I-PDU des neuen Modus gesendet.\n</li><li>Im neuen Modus erfolgen vier Zyklen mit Periodendauer t_c2; nach jeder Übertragung läuft das Intervall dt.\n</li><li>Vor dem nächsten fälligen Sendezeitpunkt schaltet das Signal mit v=a zurück.\n</li><li>Der zyklische Sendezeitpunkt von t_c2 (blau gestrichelter Pfeil) verfällt; die nächste Aussendung erfolgt unter Beachtung von t_r und nach Ablauf des Mindestabstands dt der vorherigen Aussendung.\n</li><li>Nach dieser Aussendung wird erneut das Intervall dt überwacht und die periodische Aussendung mit Zykluszeit t_c1 weitergeführt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Veranschaulicht Use Case 3 der Übertragungsmodusauswahl (TMS) gemäß AUTOSAR COM: Umschaltung zwischen zwei periodischen Übertragungsmodi (Periodic → Periodic).\n</li><li>Spezifiziert das Verhalten bei Signalwertänderungen, die einen TMS-Wechsel triggern: Der neue Übertragungsmodus übernimmt die Steuerung der Zykluszeit, wobei konfigurierte Mindestverzögerungszeiten (dt) und Reaktionszeiten (t_r, min) verhindern, dass I-PDUs unzulässig dicht aufeinanderfolgend an den Bus übergeben werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-adb98669fa1e0537", "to": "FIG-f890b8d34802e1ff", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Auslöseereignisse: Das Umschalten bzw. Aktualisieren des Signalwerts (<code>v=a</code>, <code>v=b</code>) wird von Blitzsymbolen auf nach unten gerichtete, rot konturierte Dreiecke umgestellt; zusätzlich wird zu Beginn ein Initialereignis <code>v=a</code> dargestellt.\n</li><li>Zeitparameter Umschaltverzögerung: Die Benennung <code>tr, min</code> wird durch <code>tr</code> ersetzt.\n</li><li>Sendeabfolge am Ende: Nach Rückschaltung auf <code>v=a</code> folgt ein weiterer regulärer Sendezeitpunkt im Zyklus <code>tc1</code> (insgesamt drei <code>tc1</code>-Zyklen am Ende statt zwei).\n</li><li>Mindestabstandsüberwachung (<code>dt</code>): Das erste <code>dt</code>-Intervall nach der zweiten <code>tc1</code>-Aussendung entfällt; bei der Umschaltung auf <code>v=a</code> ist das <code>dt</code>-Intervall als <code>d</code> beschriftet.\n</li><li>Zeitachse: Der reguläre Zykluszeitpunkt <code>tc2</code> wird während der Umschaltung auf <code>v=a</code> als blau gestrichelter Pfeil visualisiert, gefolgt von der tatsächlichen Aussendung nach Ablauf von <code>dt</code> bzw. <code>tr</code>.\n</li></ul>"}, {"from": "FIG-f890b8d34802e1ff", "to": "FIG-2360d72800e23134", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Mindestabstand (<code>dt</code> / Transmission Deadline / Minimum Delay Time): Unterhalb der Zeitachse ist nun nach jedem Sendeereignis (grüner Pfeil) ein dediziertes <code>dt</code>-Intervall mit gestrichelten Begrenzungen und geschweifter Klammer eingezeichnet (inklusive Korrektur der Beschriftung <code>d</code> zu <code>dt</code> bei der Umschaltung auf <code>v=a</code>).\n</li></ul>"}]};
